/* ---------- game background music: loops quietly inside the Jackpot Round and Wheel of Fortune ---------- */
const BGM_SRC="data:audio/mpeg;base64,";
const BGM={on:false,duck:0,vol:.18,last:.18,buf:null,dec:null,src:null,gain:null,t0:0,off:0,el:null,ui:null};
try{const v=parseFloat(localStorage.getItem(KEY+".bgmvol"));if(!isNaN(v)){BGM.vol=v;if(v>0)BGM.last=v}}catch(e){}
function bgmDecode(){if(BGM.buf)return Promise.resolve(BGM.buf);if(BGM.dec)return BGM.dec;const a=wfCtx();if(!a)return Promise.resolve(null);
  const raw=atob(BGM_SRC.split(",")[1]);const u=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)u[i]=raw.charCodeAt(i);
  BGM.dec=new Promise(res=>{let done=false;const ok=b=>{if(!done){done=true;BGM.buf=b;res(b)}},bad=()=>{if(!done){done=true;BGM.dec=null;res(null)}};try{const pr=a.decodeAudioData(u.buffer,ok,bad);if(pr&&pr.then)pr.then(ok,bad)}catch(e){bad()}});return BGM.dec}
function bgmPlay(){const a=wfCtx();
  if(a){bgmDecode().then(b=>{if(!b){bgmPlayEl();return}if(BGM.src||!bgmWant())return;try{if(a.state==="suspended")a.resume();
    if(!BGM.gain){BGM.gain=a.createGain();BGM.gain.connect(a.destination)}BGM.gain.gain.value=BGM.vol;
    const s=a.createBufferSource();s.buffer=b;s.loop=true;s.connect(BGM.gain);const off=BGM.off%b.duration;s.start(0,off);BGM.t0=a.currentTime-off;BGM.src=s}catch(e){bgmPlayEl()}});return}
  bgmPlayEl()}
function bgmPlayEl(){if(!BGM.el){BGM.el=document.createElement("audio");BGM.el.src=BGM_SRC;BGM.el.loop=true;BGM.el.setAttribute("playsinline","");document.body.appendChild(BGM.el)}
  BGM.el.volume=BGM.vol;const p=BGM.el.play();if(p&&p.catch)p.catch(()=>{})}
function bgmHalt(){if(BGM.src){const a=wfCtx();try{if(a&&BGM.buf)BGM.off=(a.currentTime-BGM.t0)%BGM.buf.duration;BGM.src.stop()}catch(e){}BGM.src=null}if(BGM.el){try{BGM.el.pause()}catch(e){}}}
const bgmWant=()=>BGM.on&&!BGM.duck&&BGM.vol>0&&(S.view==="jackpot"||S.view==="wheel"||S.view==="snakes");
function bgmSync(){if(BGM.gain)BGM.gain.gain.value=BGM.vol;if(BGM.el)BGM.el.volume=BGM.vol;if(bgmWant()){if(!BGM.src&&(!BGM.el||BGM.el.paused))bgmPlay()}else bgmHalt();bgmUI()}
